INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, deleted, reviewed, images) VALUES (38, '数学', '二年级', '填空', 3, '{"stem":"在□里填入合适的数：4×□=8×□","options":null}', '2；1', '4×2=8，8×1=8。注：此题为多解（□的比值为2:1，如4和2、6和3都成立），取最小正整数解：2、1。', 'paper', '[]', 0, 1, '["paper_png/yg2_sx/p021.png"]');
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, deleted, reviewed, images) VALUES (38, '数学', '二年级', '填空', 3, '{"stem":"在□里填入合适的数：3+6+9=□×3","options":null}', '6', '3+6+9=18，18=6×3，□里填6。', 'paper', '[]', 0, 1, '["paper_png/yg2_sx/p021.png"]');
