INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, deleted, reviewed, images) VALUES (38, '数学', '二年级', '填空', 3, '{"stem":"小明和他的4个小伙伴去书店买书，每人都买了5本书，他们一共买了（　）本书。","options":null}', '25本', '一共 1+4=5 人，每人5本：5×5=25（本）。', 'paper', '[]', 0, 1, '["paper_png/yg2_sx/p022.png"]');
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, deleted, reviewed, images) VALUES (38, '数学', '二年级', '填空', 3, '{"stem":"妈妈拿来一包饼干准备分给4个小朋友。她数了一下，发现如果再添上2块饼干，那么每个小朋友就可以都分到5块。这包饼干有（　）块。","options":null}', '18块', '4个小朋友各分5块共需 4×5=20（块），原有 20-2=18（块）。', 'paper', '[]', 0, 1, '["paper_png/yg2_sx/p022.png"]');
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, deleted, reviewed, images) VALUES (38, '数学', '二年级', '填空', 3, '{"stem":"松鼠妈妈采集了一些松果，这些松果的颗数比40多、比50少。把这些松果平均分给8只小松鼠，正好分完。松鼠妈妈采集了（　）颗松果，每只小松鼠分到（　）颗。","options":null}', '48颗；6颗', '40到50之间8的倍数只有48，所以共48颗；48÷8=6（颗）。', 'paper', '[]', 0, 1, '["paper_png/yg2_sx/p022.png"]');
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, deleted, reviewed, images) VALUES (38, '数学', '二年级', '单选', 2, '{"stem":"下列口诀中，只能写出一个乘法算式的是（　）。","options":["A.三四十二","B.七七四十九","C.五六三十"]}', 'B', '“七七四十九”两个因数相同，只能写 7×7=49 一个乘法算式（交换后仍是它）；三四十二可写 3×4、4×3，五六三十可写 5×6、6×5。', 'paper', '[]', 0, 1, '["paper_png/yg2_sx/p022.png"]');
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, deleted, reviewed, images) VALUES (38, '数学', '二年级', '单选', 2, '{"stem":"下面算式中，结果与5×4相同的是（　）。","options":["A.3×5+5","B.4×5-4","C.4×5+4"]}', 'A', '5×4=20；A：3×5+5=15+5=20，相同。', 'paper', '[]', 0, 1, '["paper_png/yg2_sx/p022.png"]');
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, deleted, reviewed, images) VALUES (38, '数学', '二年级', '单选', 2, '{"stem":"在□×4＜16中，□里最大能填（　）。","options":["A.4","B.3","C.9"]}', 'B', '3×4=12＜16，4×4=16 不小于16，所以最大填3。', 'paper', '[]', 0, 1, '["paper_png/yg2_sx/p022.png"]');
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, deleted, reviewed, images) VALUES (38, '数学', '二年级', '单选', 2, '{"stem":"不能用算式“3×6=18”解决的实际问题是（　）。","options":["A.每盒有6瓶牛奶，3盒有多少瓶？","B.一个货架有6罐饮料，另一个货架有3罐饮料，共有多少罐饮料？","C.蚂蚁一分钟可以爬6米，3分钟可以爬多少米？"]}', 'B', 'B 求“共有多少”，用加法 6+3=9（罐）；A、C 都是求“几个几”，可用 3×6=18。', 'paper', '[]', 0, 1, '["paper_png/yg2_sx/p022.png"]');
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, deleted, reviewed, images) VALUES (38, '数学', '二年级', '应用题', 3, '{"stem":"每辆轿车可以坐5人，3辆这样的轿车一共可以坐多少人？","options":null}', '15人', '5×3=15（人）。答：一共可以坐15人。', 'paper', '[]', 0, 1, '["paper_png/yg2_sx/p024.png"]');
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, deleted, reviewed, images) VALUES (38, '数学', '二年级', '应用题', 3, '{"stem":"有两辆轿车，一辆坐了5人，另一辆坐了3人，一共坐了多少人？","options":null}', '8人', '5+3=8（人）。答：一共坐了8人。（求“一共”用加法，与“每辆坐5人，3辆”的乘法情境相区别）', 'paper', '[]', 0, 1, '["paper_png/yg2_sx/p024.png"]');
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, deleted, reviewed, images) VALUES (38, '数学', '二年级', '应用题', 3, '{"stem":"缝纫工王阿姨负责给衣服钉扣子，每件衣服需要5个扣子，8件衣服需要多少个扣子？","options":null}', '40个', '5×8=40（个）。答：需要40个扣子。', 'paper', '[]', 0, 1, '["paper_png/yg2_sx/p024.png"]');
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, deleted, reviewed, images) VALUES (38, '数学', '二年级', '应用题', 3, '{"stem":"二（1）班同学去郊游，租了5辆面包车，每辆面包车坐6人，所有人上车后还有2个空座位。这次一共去了多少人？","options":null}', '28人', '5辆车共 5×6=30（个）座位，空2个：30-2=28（人）。答：一共去了28人。', 'paper', '[]', 0, 1, '["paper_png/yg2_sx/p024.png"]');
